#include "heston.hpp"
#include <cmath>
#include <complex>
#include <algorithm>
#include <limits>

namespace model {

namespace {
    // Constants
    constexpr double PI = 3.14159265358979323846;
    constexpr double EPSILON = 1e-15;
    constexpr double MAX_ITERATIONS = 1000;

    // Helper functions for complex logarithm with correct branch cut handling
    std::complex<double> log_complex(std::complex<double> z) {
        // Use std::log for complex numbers which handles branch cuts correctly
        return std::log(z);
    }

    // Fourier inversion for Heston model
    std::complex<double> characteristic_function(double u, double T, const Heston& h, double r, double q) {
        // Heston characteristic function
        double kappa = h.kappa;
        double theta = h.theta;
        double xi = h.xi;
        double rho = h.rho;
        double v0 = h.v0;

        // Complex parameters
        std::complex<double> i(0.0, 1.0);
        std::complex<double> d = std::sqrt((rho * xi * u * i - kappa) * (rho * xi * u * i - kappa) + 
                                           xi * xi * (u * u * i - u));
        std::complex<double> g = (kappa - rho * xi * u * i + d) / (kappa - rho * xi * u * i - d);
        std::complex<double> D = (kappa - rho * xi * u * i + d) / xi / xi;
        std::complex<double> C = (r - q) * u * i * T + kappa * theta * T * (1.0 - std::exp(-d * T)) / 
                                (d * (1.0 - g * std::exp(-d * T)));

        return std::exp(C + D * v0);
    }

    // Heston call price using Fourier inversion
    double heston_call_fourier(double S, double K, double r, double q, double T, const Heston& h) {
        // Use the Lewis (2001) approach for numerical integration
        // The integral is: C = S * P1 - K * exp(-r*T) * P2
        // where P1 and P2 are probabilities related to the characteristic function

        // Integration parameters
        double b = 100.0;  // Integration limit
        double alpha = 1.0;  // Integration parameter
        double h = 2.0 * PI / b;  // Step size

        // Numerical integration using Simpson's rule
        double sum = 0.0;
        std::complex<double> i(0.0, 1.0);

        // Compute P1 and P2 using the characteristic function
        // P1 = (1/2) + (1/pi) * integral from 0 to infinity of [Re{exp(-i*u*log(K/S)) * phi(u-i*alpha) / (i*u*phi(i*alpha))}]
        // P2 = (1/2) + (1/pi) * integral from 0 to infinity of [Re{exp(-i*u*log(K/S)) * phi(u) / (i*u*phi(i*alpha))}]

        // For numerical stability, we'll use a more robust approach
        // We'll compute the integral using a fixed number of points

        // Integration points
        int n = 1000;
        double sum1 = 0.0, sum2 = 0.0;

        // Compute the characteristic function at i*alpha for normalization
        std::complex<double> phi_alpha = characteristic_function(alpha, T, h, r, q);

        // Integration using trapezoidal rule
        for (int j = 1; j < n; j++) {
            double u = j * h;
            std::complex<double> phi_u = characteristic_function(u, T, h, r, q);
            std::complex<double> phi_u_minus_alpha = characteristic_function(u - alpha, T, h, r, q);

            // Compute the integrand for P1 and P2
            std::complex<double> integrand1 = std::exp(-i * u * std::log(K / S)) * phi_u_minus_alpha / (i * u * phi_alpha);
            std::complex<double> integrand2 = std::exp(-i * u * std::log(K / S)) * phi_u / (i * u * phi_alpha);

            // Add to sum (Simpson's rule)
            if (j % 2 == 0) {
                sum1 += 2.0 * integrand1.real();
                sum2 += 2.0 * integrand2.real();
            } else {
                sum1 += 4.0 * integrand1.real();
                sum2 += 4.0 * integrand2.real();
            }
        }

        // Add first and last terms
        std::complex<double> phi_0 = characteristic_function(0.0, T, h, r, q);
        std::complex<double> phi_0_minus_alpha = characteristic_function(-alpha, T, h, r, q);

        std::complex<double> integrand1_first = std::exp(-i * 0.0 * std::log(K / S)) * phi_0_minus_alpha / (i * 0.0 * phi_alpha);
        std::complex<double> integrand2_first = std::exp(-i * 0.0 * std::log(K / S)) * phi_0 / (i * 0.0 * phi_alpha);

        sum1 += integrand1_first.real() + integrand1_first.real();
        sum2 += integrand2_first.real() + integrand2_first.real();

        // Final results
        double P1 = 0.5 + sum1 * h / (2.0 * PI);
        double P2 = 0.5 + sum2 * h / (2.0 * PI);

        // Call price
        double call_price = S * P1 - K * std::exp(-r * T) * P2;

        // Ensure non-negativity
        return std::max(0.0, call_price);
    }

    // More robust implementation using the approach from Lewis (2001) with better numerical handling
    double heston_call_robust(double S, double K, double r, double q, double T, const Heston& h) {
        // Use the Lewis (2001) approach with proper handling of the complex logarithm
        // and branch cuts

        // Parameters
        double v0 = h.v0;
        double kappa = h.kappa;
        double theta = h.theta;
        double xi = h.xi;
        double rho = h.rho;

        // Integration parameters
        const int N = 1000;
        const double b = 100.0;
        const double h = 2.0 * PI / b;

        // Compute the normalization constant
        std::complex<double> i(0.0, 1.0);
        std::complex<double> phi_alpha = characteristic_function(1.0, T, h, r, q);

        // Compute the integral using the characteristic function
        double sum1 = 0.0;
        double sum2 = 0.0;

        // For better numerical stability, we'll compute the integral using a more careful approach
        // We'll use the fact that for small T, we can use a direct approximation
        if (T < 1e-6) {
            // For very short maturities, use a simple approximation
            double v = v0;
            double d1 = (std::log(S / K) + (r - q + 0.5 * v) * T) / std::sqrt(v * T);
            double d2 = d1 - std::sqrt(v * T);
            return S * std::exp(-q * T) * norm_cdf(d1) - K * std::exp(-r * T) * norm_cdf(d2);
        }

        // For longer maturities, use the Fourier approach
        // We'll compute the integral using a more stable method
        double alpha = 1.0;  // This is a parameter that can be tuned

        // Integration using trapezoidal rule
        for (int j = 1; j < N; j++) {
            double u = j * h;
            std::complex<double> phi_u = characteristic_function(u, T, h, r, q);
            std::complex<double> phi_u_minus_alpha = characteristic_function(u - alpha, T, h, r, q);

            // Compute the integrand
            std::complex<double> integrand1 = std::exp(-i * u * std::log(K / S)) * phi_u_minus_alpha / (i * u * phi_alpha);
            std::complex<double> integrand2 = std::exp(-i * u * std::log(K / S)) * phi_u / (i * u * phi_alpha);

            // Add to sum
            sum1 += integrand1.real();
            sum2 += integrand2.real();
        }

        // Add first and last terms
        std::complex<double> phi_0 = characteristic_function(0.0, T, h, r, q);
        std::complex<double> phi_0_minus_alpha = characteristic_function(-alpha, T, h, r, q);

        std::complex<double> integrand1_first = std::exp(-i * 0.0 * std::log(K / S)) * phi_0_minus_alpha / (i * 0.0 * phi_alpha);
        std::complex<double> integrand2_first = std::exp(-i * 0.0 * std::log(K / S)) * phi_0 / (i * 0.0 * phi_alpha);

        sum1 += integrand1_first.real();
        sum2 += integrand2_first.real();

        // Final results
        double P1 = 0.5 + sum1 * h / (2.0 * PI);
        double P2 = 0.5 + sum2 * h / (2.0 * PI);

        // Call price
        double call_price = S * P1 - K * std::exp(-r * T) * P2;

        // Ensure non-negativity
        return std::max(0.0, call_price);
    }

    // Standard normal CDF
    double norm_cdf(double x) {
        // Using the approximation from Abramowitz and Stegun
        double a1 =  0.254829592;
        double a2 = -0.284496736;
        double a3 =  1.421413741;
        double a4 = -1.453152027;
        double a5 =  1.061405429;
        double p  =  0.3275911;

        int sign = 1;
        if (x < 0)
            sign = -1;
        x = std::abs(x) / std::sqrt(2.0);

        double t = 1.0 / (1.0 + p * x);
        double y = 1.0 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * std::exp(-x * x);

        return 0.5 * (1.0 + sign * y);
    }

    // More accurate implementation using the approach from Gatheral
    double heston_call_gatheral(double S, double K, double r, double q, double T, const Heston& h) {
        // Use the approach from Gatheral's book with proper numerical handling
        // This is a more robust implementation

        // Parameters
        double v0 = h.v0;
        double kappa = h.kappa;
        double theta = h.theta;
        double xi = h.xi;
        double rho = h.rho;

        // For very short maturities, use Black-Scholes approximation
        if (T < 1e-8) {
            double v = v0;
            double d1 = (std::log(S / K) + (r - q + 0.5 * v) * T) / std::sqrt(v * T);
            double d2 = d1 - std::sqrt(v * T);
            return S * std::exp(-q * T) * norm_cdf(d1) - K * std::exp(-r * T) * norm_cdf(d2);
        }

        // Use the Lewis (2001) approach with better numerical handling
        const int N = 1000;
        const double b = 100.0;
        const double h = 2.0 * PI / b;
        const double alpha = 1.0;

        std::complex<double> i(0.0, 1.0);

        // Compute normalization constant
        std::complex<double> phi_alpha = characteristic_function(alpha, T, h, r, q);

        // Integration using trapezoidal rule
        double sum1 = 0.0;
        double sum2 = 0.0;

        for (int j = 1; j < N; j++) {
            double u = j * h;
            std::complex<double> phi_u = characteristic_function(u, T, h, r, q);
            std::complex<double> phi_u_minus_alpha = characteristic_function(u - alpha, T, h, r, q);

            // Compute the integrand
            std::complex<double> integrand1 = std::exp(-i * u * std::log(K / S)) * phi_u_minus_alpha / (i * u * phi_alpha);
            std::complex<double> integrand2 = std::exp(-i * u * std::log(K / S)) * phi_u / (i * u * phi_alpha);

            sum1 += integrand1.real();
            sum2 += integrand2.real();
        }

        // Add first and last terms
        std::complex<double> phi_0 = characteristic_function(0.0, T, h, r, q);
        std::complex<double> phi_0_minus_alpha = characteristic_function(-alpha, T, h, r, q);

        std::complex<double> integrand1_first = std::exp(-i * 0.0 * std::log(K / S)) * phi_0_minus_alpha / (i * 0.0 * phi_alpha);
        std::complex<double> integrand2_first = std::exp(-i * 0.0 * std::log(K / S)) * phi_0 / (i * 0.0 * phi_alpha);

        sum1 += integrand1_first.real();
        sum2 += integrand2_first.real();

        // Final results
        double P1 = 0.5 + sum1 * h / (2.0 * PI);
        double P2 = 0.5 + sum2 * h / (2.0 * PI);

        // Call price
        double call_price = S * P1 - K * std::exp(-r * T) * P2;

        // Ensure non-negativity
        return std::max(0.0, call_price);
    }
}

double heston_call(double S, double K, double r, double q, double T, const Heston& h) {
    return heston_call_gatheral(S, K, r, q, T, h);
}

double heston_put(double S, double K, double r, double q, double T, const Heston& h) {
    // Use put-call parity: P = C - S + K*exp(-r*T) + q*S*exp(-q*T)
    double call_price = heston_call(S, K, r, q, T, h);
    return call_price - S * std::exp(-q * T) + K * std::exp(-r * T);
}

}  // namespace model

