    24	double heston_put(double S, double K, double r, double q, double T, const Heston& h) {
    25	    // Use put-call parity: P = C - S + K*exp(-r*T) + q*S*exp(-q*T)
    26	    double call_price = heston_call(S, K, r, q, T, h);
    27	    return call_price - S * std::exp(-q * T) + K * std::exp(-r * T);
    28	}
